function* g() {
  for (var idx = 0; idx < 3; idx++) {
    yield idx;
  }
}
var iter = g();
var result;

result = iter.next();
assert.sameValue(result.value, 0, 'First result `value`');
assert.sameValue(result.done, false, 'First result `done` flag');

result = iter.next();
